#!/usr/bin/env python3
"""Gzip web/logger.html into src/default/logger_html.h (served from flash).

Run after editing web/logger.html:  python3 tools/embed_html.py
"""
import gzip
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
src = root / "web" / "logger.html"
dst = root / "src" / "default" / "logger_html.h"

data = gzip.compress(src.read_bytes(), compresslevel=9, mtime=0)
lines = [",".join(f"0x{b:02x}" for b in data[i:i + 32]) for i in range(0, len(data), 32)]
dst.write_text(
    "// Generated by tools/embed_html.py from web/logger.html. Do not edit.\n"
    "#ifndef LOGGER_HTML_H\n#define LOGGER_HTML_H\n\n#include <Arduino.h>\n\n"
    f"#define logger_html_len {len(data)}\n\n"
    "const uint8_t logger_html[] PROGMEM = {\n" + ",\n".join(lines) + "\n};\n\n#endif\n"
)
print(f"{src.name}: {src.stat().st_size} bytes -> {len(data)} bytes gzipped")
